begin;
do $test$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();p uuid:=gen_random_uuid();z uuid:=gen_random_uuid();q uuid:=gen_random_uuid();k uuid:=gen_random_uuid();r public.esg_projects;s public.esg_projects;x public.esg_projects;checks integer:=0;
begin
 begin
 insert into auth.users(id) values(a),(b),(p),(z),(q);
 insert into public.profiles(id,display_name,role,approved) values(a,'Student','aluno',false),(b,'Other','aluno',false),(p,'Professional','profissional',true),(z,'Admin','admin',false),(q,'Other admin','admin',false);
 set local role authenticated;perform set_config('request.jwt.claims',json_build_object('sub',a,'is_anonymous',false)::text,true);
select * into r from public.submit_esg_project(k,'social',' Test project ',' Description ');if r.owner_id<>a or r.title<>'Test project' or r.description<>'Description' or r.status<>'pending' or r.version<>1 or r.reviewed_at is not null then raise exception 'invalid submitted row';end if;checks:=checks+1;
select * into s from public.submit_esg_project(k,'social','Test project','Description');if s.id<>r.id or (select count(*) from public.esg_projects)<>1 then raise exception 'duplicate';end if;checks:=checks+1;
begin perform public.submit_esg_project(k,'social','Other','Description');raise exception 'unexpected permitted operation';exception when unique_violation then checks:=checks+1;end;
begin perform public.submit_esg_project(gen_random_uuid(),'invalid','Title','Body');raise exception 'unexpected permitted operation';exception when invalid_parameter_value then checks:=checks+1;end;
