begin insert into public.esg_projects(owner_id,request_id,category,title,description) values(a,k,'social','Title','Body');raise exception 'unexpected permitted operation';exception when insufficient_privilege then checks:=checks+1;end;
begin update public.esg_projects set status='approved' where id=r.id;raise exception 'unexpected permitted operation';exception when insufficient_privilege then checks:=checks+1;end;
begin delete from public.esg_projects where id=r.id;raise exception 'unexpected permitted operation';exception when insufficient_privilege then checks:=checks+1;end;
