select * into s from public.review_esg_project(s.id,1,'rejected','Needs evidence');if s.status<>'rejected' or s.version<>2 then raise exception 'reject failed';end if;checks:=checks+1;
perform set_config('request.jwt.claims',json_build_object('sub',q,'is_anonymous',false)::text,true);
begin perform public.review_esg_project(r.id,1,'approved','Evidence checked');raise exception 'unexpected permitted operation';exception when insufficient_privilege then checks:=checks+1;end;
perform set_config('request.jwt.claims',json_build_object('sub',a,'is_anonymous',false)::text,true);
if (select count(*) from public.esg_project_reviews)<>1 then raise exception 'own decision visibility';end if;checks:=checks+1;
select * into r from public.submit_esg_project(k,'social','Test project','Description');if r.status<>'approved' then raise exception 'replay after decision';end if;checks:=checks+1;
reset role;update public.profiles set role='admin' where id=p;set local role authenticated;perform set_config('request.jwt.claims',json_build_object('sub',p,'is_anonymous',false)::text,true);
begin perform public.review_esg_project(x.id,1,'approved','Self after promotion');raise exception 'unexpected permitted operation';exception when insufficient_privilege then checks:=checks+1;end;
perform set_config('request.jwt.claims',json_build_object('sub',z,'is_anonymous',true)::text,true);
if exists(select 1 from public.esg_projects) or exists(select 1 from public.esg_project_reviews) then raise exception 'anonymous Auth reads';end if;checks:=checks+1;
begin perform public.review_esg_project(x.id,1,'approved','Anonymous admin');raise exception 'unexpected permitted operation';exception when insufficient_privilege then checks:=checks+1;end;
